package dev.jackteng.encore;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.jackteng.encore.admission.AdmissionSettings;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.StockProjectionService.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockProjectionIntegrationTest {
 @Autowired StockProjectionService projections;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;
 @Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired OrderService orders;@Autowired PaymentService payments;@Autowired PurchaseService purchases;@Autowired PlatformTransactionManager transactions;
 RedisTicketLedger ledger;final Set<String> ownKeys=new HashSet<>();String manager="projection-"+UUID.randomUUID();
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(ownKeys);ownKeys.clear();}
 UUID ticket(){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"projection-"+UUID.randomUUID(),"核對演出","合成","合成"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",OffsetDateTime.now().plusDays(2),OffsetDateTime.now().minusHours(1),OffsetDateTime.now().plusHours(2)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);return t.id();}
 CustomerService.Principal customer(){var c=customers.register("pr-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Place place(UUID t){return new Place(UUID.randomUUID(),t,1,1,1200);}
 Rebuild begin(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());ownKeys.add(ledger.key(t,c.generation()));return c;}
 Rebuild ready(UUID t){var c=begin(t);assertEquals("READY",projections.complete(c.requestId()).state());return c;}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 long journal(UUID t){return db.queryForObject("SELECT count(*) FROM stock_revision WHERE ticket_id=?",Long.class,t);}

 @Test void initialJournalMatchesFormalStockAndNoGenerationIsOpen(){var t=ticket();var g=projections.inspect(t);assertEquals("DIRTY",g.state());assertEquals(0,g.generation());assertEquals(1,g.sourceRevision());assertEquals(1,journal(t));assertEquals(4,db.queryForObject("SELECT capacity-held-sold FROM stock_revision WHERE ticket_id=?",Integer.class,t));}
 @Test void committedClosedEpochPrecedesRedisAndUuidDoesNotAllocateTwice(){var t=ticket();var c=begin(t);assertEquals("CLOSED",projections.inspect(t).state());assertFalse(redis.hasKey(ledger.key(t,1)));assertEquals(c,projections.begin(t,c.requestId(),1));assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_rebuild_command WHERE ticket_id=?",Integer.class,t));assertEquals("READY",projections.complete(c.requestId()).state());assertEquals(4,projections.inspect(t).preparedAvailable());assertEquals("READY",projections.complete(c.requestId()).state());assertEquals(1,projections.inspect(t).generation());}
 @Test void sixConcurrentSameUuidAllocateOneDurableGeneration()throws Exception {var t=ticket();var request=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<Rebuild>>();for(int i=0;i<6;i++)jobs.add(()->projections.begin(t,request,1));for(var f:pool.invokeAll(jobs)){var c=f.get();ownKeys.add(ledger.key(t,c.generation()));assertEquals(1,c.generation());assertEquals(request,c.requestId());}}assertEquals(1,projections.inspect(t).generation());assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_rebuild_command WHERE ticket_id=?",Integer.class,t));}
 @Test void requestIdentityBindsTicketAndSourceRevision(){var t=ticket();var other=ticket();var c=begin(t);problem("REBUILD_CONFLICT",()->projections.begin(other,c.requestId(),1));problem("REBUILD_CONFLICT",()->projections.begin(t,c.requestId(),2));assertEquals(0,projections.inspect(other).generation());assertEquals(1,projections.inspect(t).generation());}
 @Test void staleBeginDoesNotConsumeGeneration(){var t=ticket();db.update("UPDATE ticket_type SET capacity=capacity+1 WHERE id=?",t);problem("STOCK_CHANGED",()->projections.begin(t,UUID.randomUUID(),1));assertEquals(0,projections.inspect(t).generation());assertEquals(2,journal(t));}
 @Test void supersededClosedCommandCannotOpenAnOldEpoch(){var t=ticket();var old=begin(t);var fresh=begin(t);problem("GENERATION_FENCED",()->projections.complete(old.requestId()));assertFalse(redis.hasKey(ledger.key(t,old.generation())));assertEquals("READY",projections.complete(fresh.requestId()).state());assertEquals(2,projections.inspect(t).generation());}
 @Test void pgStockChangeBetweenPhasesInvalidatesOriginalSnapshot(){var t=ticket();var c=begin(t);orders.place(customer(),place(t));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(c,projections.begin(t,c.requestId(),1));problem("STOCK_CHANGED",()->projections.complete(c.requestId()));var fresh=ready(t);assertEquals(3,fresh.available());assertEquals(2,fresh.generation());}
 @Test void syncHoldAndCancellationEachRecordRevisionAndInvalidateReady(){var t=ticket();ready(t);var c=customer();var o=orders.place(c,place(t));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(2,journal(t));ready(t);orders.cancel(c,o.id(),new Cancel(UUID.randomUUID(),o.version()));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(3,journal(t));assertEquals(4,ready(t).available());}
 @Test void paymentConversionInvalidatesEvenThoughFreeStockUnchanged(){var t=ticket();var c=customer();var o=orders.place(c,place(t));ready(t);var paid=payments.start(c,o.id(),new PaymentModels.Pay(UUID.randomUUID(),o.version(),1200,"SUCCESS"));payments.reconcile(c,o.id(),paid.payment().id(),new PaymentModels.Reconcile(UUID.randomUUID()));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(3,journal(t));var r=db.queryForMap("SELECT held,sold FROM stock_revision WHERE ticket_id=? AND revision=3",t);assertEquals(0,r.get("held"));assertEquals(1,r.get("sold"));assertEquals(3,ready(t).available());}
 @Test void actualExpiryReleaseInvalidatesProjection(){var t=ticket();var o=orders.place(customer(),place(t));ready(t);db.update("UPDATE ticket_order SET expires_at=created_at+interval '1 millisecond' WHERE id=?",o.id());assertTrue(orders.expire(o.id()));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(3,journal(t));assertEquals(4,ready(t).available());}
 @Test void asyncWorkerUsesSameTriggerForFinalFormalHold(){var t=ticket();ready(t);var c=customer();var p=purchases.submit(c,place(t));assertEquals("READY",projections.inspect(t).state());var event=db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());assertTrue(purchases.process(event));assertEquals("DIRTY",projections.inspect(t).state());assertEquals(2,journal(t));assertEquals(3,ready(t).available());}
 @Test void pgRollbackRestoresTicketJournalAndGateTogether(){var t=ticket();var c=ready(t);var original=projections.inspect(t);new TransactionTemplate(transactions).execute(tx->{db.update("UPDATE ticket_type SET held=held+1 WHERE id=?",t);assertEquals("DIRTY",projections.inspect(t).state());tx.setRollbackOnly();return null;});assertEquals(original,projections.inspect(t));assertEquals(1,journal(t));assertEquals("READY",projections.complete(c.requestId()).state());}
 @Test void journalInsertFailureRollsBackFormalOrderAndGate(){var t=ticket();ready(t);var c=customer();var original=projections.inspect(t);db.execute("ALTER TABLE stock_revision ADD CONSTRAINT m4d2_journal_fault CHECK(ticket_id<>'"+t+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->orders.place(c,place(t)));assertEquals(original,projections.inspect(t));assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,c.id()));}finally{db.execute("ALTER TABLE stock_revision DROP CONSTRAINT m4d2_journal_fault");}}
 @Test void redisOpenBeforePgReadyFailureRemainsDurablyClosedAndReplayable(){var t=ticket();var c=begin(t);db.execute("ALTER TABLE stock_projection ADD CONSTRAINT m4d2_ready_fault CHECK(NOT(ticket_id='"+t+"'::uuid AND state='READY')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->projections.complete(c.requestId()));assertEquals("CLOSED",projections.inspect(t).state());assertEquals(RedisTicketLedger.Phase.OPEN,ledger.snapshot(t,1).snapshot().phase());}finally{db.execute("ALTER TABLE stock_projection DROP CONSTRAINT m4d2_ready_fault");}assertEquals("READY",projections.complete(c.requestId()).state());assertEquals(1,projections.inspect(t).generation());}
 @Test void readyKeyLossNeedsNewPgEpochNeverSameGenerationReseed(){var t=ticket();var c=ready(t);redis.delete(ledger.key(t,1));var failed=projections.complete(c.requestId());assertEquals("DIRTY",failed.state());assertEquals("REDIS_MISSING",failed.failure());assertFalse(redis.hasKey(ledger.key(t,1)));problem("STOCK_CHANGED",()->projections.complete(c.requestId()));var next=ready(t);assertEquals(2,next.generation());assertFalse(redis.hasKey(ledger.key(t,1)));assertNotEquals(ledger.key(t,1),ledger.key(t,2));}
 @Test void wrongTypeAndTtlNeverGetOverwrittenByRecovery(){var t=ticket();var c=ready(t);var key=ledger.key(t,1);redis.delete(key);redis.opsForValue().set(key,"synthetic wrong type");assertEquals("DIRTY",projections.complete(c.requestId()).state());assertEquals("synthetic wrong type",redis.opsForValue().get(key));var next=ready(t);redis.expire(ledger.key(t,next.generation()),Duration.ofMinutes(1));assertEquals("DIRTY",projections.complete(next.requestId()).state());assertTrue(redis.getExpire(ledger.key(t,next.generation()))>0);}
 @Test void uncoordinatedHeldReceiptIsNotResetOrReleased(){var t=ticket();var c=ready(t);var claim=new RedisTicketLedger.Claim(1,UUID.randomUUID(),UUID.randomUUID(),1,System.currentTimeMillis()+60000,"b".repeat(64));ledger.hold(t,claim);assertEquals("DIRTY",projections.complete(c.requestId()).state());assertEquals(RedisTicketLedger.Status.HELD,ledger.lookup(t,claim).receipt().status());assertEquals(3,ledger.snapshot(t,1).snapshot().available());}
 @Test void immutableJournalAndCommandCannotBeEditedOrDeleted(){var t=ticket();var c=begin(t);for(String sql:List.of("UPDATE stock_revision SET held=held WHERE ticket_id=?","DELETE FROM stock_revision WHERE ticket_id=?","UPDATE stock_rebuild_command SET available=available WHERE ticket_id=?","DELETE FROM stock_rebuild_command WHERE ticket_id=?"))assertThrows(org.springframework.dao.DataAccessException.class,()->db.update(sql,t));assertEquals(c,projections.begin(t,c.requestId(),1));}
 @Test void stableSnapshotWaitsForActualTicketWriterBeforeCheckingRevision()throws Exception {var t=ticket();var c=begin(t);try(var pool=Executors.newSingleThreadExecutor()){var future=new TransactionTemplate(transactions).execute(tx->{db.queryForObject("SELECT id FROM ticket_type WHERE id=? FOR UPDATE",UUID.class,t);var work=pool.submit(()->problem("STOCK_CHANGED",()->projections.complete(c.requestId())));boolean waiting=false;for(int i=0;i<60;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND query LIKE '%stock projection guard%'",Integer.class)>0){waiting=true;break;}try{Thread.sleep(25);}catch(InterruptedException e){throw new AssertionError(e);}}assertTrue(waiting);db.update("UPDATE ticket_type SET capacity=capacity+1 WHERE id=?",t);return work;});future.get(3,TimeUnit.SECONDS);}assertEquals("DIRTY",projections.inspect(t).state());assertFalse(redis.hasKey(ledger.key(t,1)));}
 @Test void quoteVersionChangeButNoopInventoryUpdateHandledPrecisely(){var t=ticket();ready(t);db.update("UPDATE ticket_type SET held=held WHERE id=?",t);assertEquals(1,journal(t));assertEquals("READY",projections.inspect(t).state());db.update("UPDATE ticket_type SET version=version+1 WHERE id=?",t);assertEquals(2,journal(t));assertEquals("DIRTY",projections.inspect(t).state());}
 @Test void maintenanceCannotHideAnUncommittedOuterTransaction(){var t=ticket();new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->begin(t));return null;});assertEquals(0,projections.inspect(t).generation());}
 @Test void readyConstraintRequiresRealPreparedRevisionAndSqlBoundsHold(){var t=ticket();begin(t);assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE stock_projection SET state='READY',prepared_available=4 WHERE ticket_id=?",t));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("UPDATE stock_projection SET generation=1000000001 WHERE ticket_id=?",t));assertEquals("CLOSED",projections.inspect(t).state());}
 @Test void delayedOldInitCannotTouchTheCurrentDurableEpoch(){var t=ticket();var old=ready(t);var fresh=ready(t);redis.delete(ledger.key(t,old.generation()));ledger.initialize(t,old.generation(),99,4096);ledger.open(t,old.generation());assertEquals(99,ledger.snapshot(t,old.generation()).snapshot().available());assertEquals(4,ledger.snapshot(t,fresh.generation()).snapshot().available());problem("GENERATION_FENCED",()->projections.complete(old.requestId()));assertEquals("READY",projections.complete(fresh.requestId()).state());assertThrows(IllegalStateException.class,()->ledger.rotate(t,fresh.generation(),99));}
 @Test void concurrentCrossTicketUuidConflictRollsBackLoserEpoch()throws Exception {var a=ticket();var b=ticket();var request=UUID.randomUUID();int winners=0;try(var pool=Executors.newFixedThreadPool(2)){var jobs=List.<Callable<String>>of(()->{try{projections.begin(a,request,1);return "OK";}catch(Problem e){return e.code;}},()->{try{projections.begin(b,request,1);return "OK";}catch(Problem e){return e.code;}});for(var f:pool.invokeAll(jobs)){var code=f.get();if(code.equals("OK"))winners++;else assertEquals("REBUILD_CONFLICT",code);}}assertEquals(1,winners);assertEquals(1,projections.inspect(a).generation()+projections.inspect(b).generation());}
}
